function registerUser(form: SignupForm): void {
	if (!form.email.includes("@")) throw new Error("invalid email");
	if (form.password.length < 12) throw new Error("weak password");
	const user = { email: form.email, hash: hashPassword(form.password) };
	db.insert("users", user);
	mailer.send(form.email, "Welcome!", renderWelcomeTemplate(user));
	logger.info(`registered ${form.email}`);
}

